import{_ as a,o as s,c as e,ag as p}from"./chunks/framework.PVHj0As1.js";const t="/pub-blog/assets/image-20260309093002883.DUuaBqe4.png",o="/pub-blog/assets/image-20260310000844140.naVi3SEc.png",l="/pub-blog/assets/image-20260310000753476.zKLA8RVb.png",i="data:image/png;base64,",r="/pub-blog/assets/image-20260310001119865.B80Q0WDI.png",c="/pub-blog/assets/image-20260310001131856.Cojlau1u.png",g="/pub-blog/assets/image-20260310001251137.D23wAceh.png",b="/pub-blog/assets/image-20260310001309469.DIqurWcF.png",u="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",_=JSON.parse('{"title":"小龙虾（openclaw），轻松玩转自动发帖","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/小龙虾（openclaw），轻松玩转自动发帖/小龙虾（openclaw），轻松玩转自动发帖.md","filePath":"AI人工智能/小龙虾（openclaw），轻松玩转自动发帖/小龙虾（openclaw），轻松玩转自动发帖.md","lastUpdated":1773073248000,"__rawMarkdown":"# 小龙虾（openclaw），轻松玩转自动发帖\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 前言\\n\\n很多小伙伴说安装了小龙虾之后，不知道可以做一些什么，那么这里可以提供一些好玩的场景，比如**自动发**帖，这里主要通过**稀土掘金**来演示。\\n\\n\\n\\n> 如果大家还没有安装好小龙虾（openclaw），可以参考这个内容先去安装，也可以联系我寻求帮助。\\n>\\n> https://mp.weixin.qq.com/s/OD7Hg0stvySFlCrtFBXo1A\\n\\n### 交流群 [](#交流群)\\n\\n万少建立了一个专门讨论小龙虾OpenClaw的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n\\n![](assets/image-20260309093002883.DUuaBqe4.png)\\n\\n## 过程分析讲解\\n\\n我们一般都会在**默认的浏览器**上进行日常的活动，也会在上面**登录好账号**，\\n\\n那么这样**openclaw**就可以在默认的浏览器上去操作一些我们想要的功能\\n\\n比如自动发帖。\\n\\n自动发帖也大概分成3种方式：\\n\\n1. 已有的一些网站或者服务提供了MCP，那么我们就可以直接对接，这个方式最安全和合理，但是也需要看这个网站是否提供有对\\n\\n   应的MCP服务，如果一般有，我们可以安装对应的skill去测试试用下。\\n\\n2. 直接对接API的方式，这个方式不太建议，因为相当于绕开了正常用户的操作流程，用非法的手段去操作发帖了。\\n\\n3. **托管浏览器的方式，这个方式可以让openclaw模拟用户的操作去走完发帖的流程。**\\n\\n\\n\\n## 配置openclaw托管浏览器\\n\\n1. 打开你常用的浏览器，安装浏览器插件 `OpenClaw Browser Relay`\\n\\n   `这一步不会操作的话，也可以q我`\\n\\n   ![](assets/image-20260310000844140.png)\\n\\n2. 找到你系统目录下的  openclaw.json 配置文件，复制其中的token\\n\\n   ```\\n     \\"gateway\\": {\\n       \\"mode\\": \\"local\\",\\n       \\"auth\\": {\\n         \\"mode\\": \\"token\\",\\n         \\"token\\": \\"xxxxx\\"\\n       }\\n     },\\n   ```\\n\\n3. 然后回到浏览器上，打开 `OpenClaw Browser Relay` 插件，粘贴进去你的 token配置\\n\\n   ![](assets/image-20260310000753476.png)\\n\\n4. 然后点击一下浏览器工具栏上的图标，出现\\"On\\"表示已经设置好。\\n\\n   ![](assets/image-20260310001007769.png)\\n\\n5. 顺利的话，你的浏览器会出现提示。\\n\\n   ![](assets/image-20260310001119865.png)\\n\\n## 然后提前登录你需要操作的平台\\n\\n比如稀土掘金，提前登录好。\\n\\n![](assets/image-20260310001131856.png)\\n\\n## 然后就可以输入内容了\\n\\n如：\\n\\n![](assets/image-20260310001251137.png)\\n\\n---\\n\\n**运行结果**\\n\\n![](assets/image-20260310001309469.png)\\n\\n当然，过程中我也踩了一些坑。\\n\\n## 提效\\n\\n我也将整个流程打包成skill发布到clawhub上了，后期你只需要这样说就行了\\n\\n```\\n使用 juejin-pins-publish 这个skill 帮我发布xxx内容到稀土掘金的沸点上。\\n```\\n\\n\\n\\n\\n\\n* * *\\n\\n## 最后 [](#最后)\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),h={name:"AI人工智能/小龙虾（openclaw），轻松玩转自动发帖/小龙虾（openclaw），轻松玩转自动发帖.md"};function m(d,n,A,w,q,k){return s(),e("div",null,[...n[0]||(n[0]=[p("",33)])])}const x=a(h,[["render",m]]);export{_ as __pageData,x as default};
